def flaky(state):
    state['calls'] += 1
    if state['calls'] < 3:
        raise RuntimeError('429 rate limited')
    return 'ok'

def call_with_retry(fn, state, attempts=4):
    last = None
    for _ in range(attempts):
        try:
            return fn(state)
        except RuntimeError as exc:
            last = exc
    raise last

state = {'calls': 0}
result = call_with_retry(flaky, state)
print(result, state['calls'])

