# M.0 - teen gates, ek hi loop: allowlist -> budget -> approval
TOOLS = {
    "status": lambda oid: {"order_id": oid, "state": "delivered"},
    "refund": lambda oid: {"refund_id": "R-" + oid[-3:], "order_id": oid},
}

def run(plan, tools=TOOLS, max_steps=3, approve=None):
    trace, used = [], 0
    for name, args in plan:
        if used >= max_steps:                      # gate 1: budget
            return {"status": "stopped", "why": "max_steps", "trace": trace}
        used += 1
        if name not in tools:                      # gate 2: allowlist
            trace.append(("blocked", name, "not_in_allowlist"))
            continue
        if name == "refund" and not (approve and approve(args)):
            trace.append(("paused", name, "needs_approval"))   # gate 3: HITL
            continue
        trace.append((name, tools[name](**args)))
    return {"status": "done", "trace": trace}

plan = [("status", {"oid": "A-100"}), ("refund", {"oid": "A-100"})]
print("no approval :", run(plan))
print("approved    :", run(plan, approve=lambda args: args["oid"] == "A-100"))
print("unknown tool:", run([("delete_all", {})] * 5))
